def acquire_object(ref):
    if is_holding(ref):
        return True
    if walk(ref).status != 'succeeded':
        return False
    return grab(ref).status == 'succeeded'

def ensure_open(container):
    if walk(container).status != 'succeeded':
        return False
    states = get_object_states(container)
    if states is None:
        return False
    return 'OPEN' in states or open(container).status == 'succeeded'

def place_held_in_container(obj, container):
    if not is_holding(obj):
        return False
    if not ensure_open(container):
        return False
    return putin(obj, container).status == 'succeeded'

def load_washing_machine(clothes, machine):
    if not place_held_in_container(clothes, machine):
        return False
    return close(machine).status == "succeeded"

def run_wash_cycle(machine):
    if switchon(machine).status != "succeeded":
        return False
    return switchoff(machine).status == "succeeded"

def unload_washing_machine(clothes, machine):
    if not ensure_open(machine):
        return False
    if grab(clothes).status != "succeeded":
        return False
    return close(machine).status == "succeeded"
